--
-- Name: books; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.books (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    title text NOT NULL,
    author text NOT NULL,
    description text DEFAULT ''::text NOT NULL,
    genre text DEFAULT 'General'::text NOT NULL,
    cover_url text DEFAULT ''::text NOT NULL,
    status text DEFAULT 'Available'::text NOT NULL,
    borrowed_by uuid,
    expires_at timestamp with time zone,
    borrow_count integer DEFAULT 0 NOT NULL,
    year integer,
    pages integer,
    isbn text,
    language text DEFAULT 'ไทย'::text NOT NULL,
    featured boolean DEFAULT false NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    pdf_url text DEFAULT ''::text,
    max_borrow_days integer DEFAULT 14 NOT NULL,
    CONSTRAINT books_status_check CHECK ((status = ANY (ARRAY['Available'::text, 'Borrowed'::text])))
);


--
-- Name: borrow_history; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.borrow_history (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    book_id uuid NOT NULL,
    user_id uuid NOT NULL,
    borrowed_at timestamp with time zone DEFAULT now() NOT NULL,
    returned_at timestamp with time zone,
    expired boolean DEFAULT false NOT NULL
);


--
-- Name: users; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.users (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    email text NOT NULL,
    password_hash text NOT NULL,
    display_name text DEFAULT ''::text NOT NULL,
    role text DEFAULT 'member'::text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT users_role_check CHECK ((role = ANY (ARRAY['member'::text, 'admin'::text])))
);


